        "literal": "Shall I to the moment say: / Linger yet! you are so beautiful! / Then may you me into fetters strike, / Then will I gladly to ruin go!",
        "translations": {
          "kaufmann_faust": "If ever I say to the moment: / Linger awhile! you are so fair! / Then you may cast me into fetters, / then I will gladly perish there!",
          "luke_faust": "If ever I say to the passing moment: / 'Stay awhile yet! thou art so fair!' / Then you may cast me into chains, / Then I will gladly perish there!",
          "arndt_faust": "If ever to the moment I should say: / 'Abide, you are so fair!' / Then you may cast me into fetters, / Then will I gladly perish there!",
          "greenberg_faust": "If I should ever say to the passing moment: / 'Stay awhile! You are so fair!' / Then you may clamp the irons on me, / Then I will gladly perish there!",
          "taylor_faust": "When thus I hail the Moment flying: / 'Ah, still delay—thou art so fair!' / Then bind me in thy bonds undying, / My final ruin then declare!",
          "atkins_faust": "If ever I say to the passing moment: / 'Tarry awhile! you are so fair!' / Then you may clap me into irons, / then I will gladly go to ruin!",
          "wayne_faust": "If ever to the passing hour I say: / 'Linger awhile! you are so fair!' / Then may you cast me into chains, / Then will I gladly perish there!",
          "anster_faust": "If ever I to any moment say, / 'Fair vision, linger!—go not yet away!' / Then throw around me the eternal chain, / Then will I gladly perish in my pain!",
          "ref": "Goe.Faust.1699",
          "blackie_faust": "If ever to the passing hour I say: / 'Tarry a while, thou art so fair!' / Then mayst thou bind me in thy chains, / Then will I perish willingly!",
          "latham_faust": "If to the fleeting hour I say: / 'Linger awhile, thou art so fair!' / Then mayst thou cast me into bonds, / Then will I gladly perish!",
          "priest_faust": "If to the fleeting hour I say: / 'Remain, so fair thou art, remain!' / Then you may cast me into fetters, / Then will I gladly perish!",
          "martin_faust": "If to the fleeting moment I shall say: / 'Stay! Thou art so fair!' / Then bind me in thy fetters fast, / Then gladly will I perish!",
          "macneice_faust": "If I should ever say to the passing moment: / 'Tarry awhile, you are so fair!' / Then you may clap me into irons, / Then will I gladly die!",
          "salm_faust": "If ever I say to the moment: / 'Linger awhile! you are so fair!' / then you may cast me into chains, / then will I gladly perish!",
          "passage_faust": "If to the passing moment I should say: / 'Abide awhile, thou art so fair!' / Then you may throw me into chains, / Then will I gladly perish!"
        },
        "notes": "The famous terms of the wager (Wette): Faust's soul is forfeit not upon bodily death, but only if he ever succumbs to passive satisfaction with mortal experience.",
