          "mcgowan_baud": "Infatuation, sadism, lust, and greed / Possess our minds and work upon our flesh,",
          "waldrop_baud": "Stupidity, error, sin, pettiness / occupy our minds and work on our bodies,",
          "aggeler_baud": "Folly, error, sin, and avarice / Occupy our minds and labor our bodies,",
          "symons_baud": "Folly and error, avarice and sin, / Possess our souls and body night and day,",
          "campbell_baud": "Folly and error, avarice and vice / Employ our souls and waste our bodies' force,",
          "lowell_baud": "Stupidity, greed, guilt, and buggery / gnaw at our minds, and undermine our flesh,",
          "shanks_baud": "Folly and error, avarice and sin, / Possess our spirits and our bodies wear,",
