        "sectionId": "cp-siberian-epilogue",
        "source": "Они оба были бледны и худы; но в этих больных и бледных лицах уже сияла заря обновленного будущего, полного воскресения в новую жизнь.",
        "literal": "They both were pale and thin; but in these sick and pale faces already shone dawn of renewed future, of full resurrection into new life.",
