          "mitchell_onegin": "'My uncle, man of highest principle, / when he fell gravely ill, declared / himself the master, invincible, / and won respect he never shared.",
          "falikov_onegin": "'My uncle, of the highest principles, / When he fell dangerously ill, / Won our respect, though not through miracles, / And proved he had the stronger will.",
