          "mitchell_onegin": "'I love you (why dissemble now?), / But I have been another's given; / To him I'll be forever true.'",
          "falikov_onegin": "'I love you (why should I dissemble?), / But I am now another's wife, / And will be faithful all my life.'",
          "arndt_onegin": "'I love you (why should I deny it?), / But I was given to another, / And to him will be faithful all my life.'",
