        "source": "«Tous les événements sont enchaînés dans le meilleur des mondes possibles; car enfin, si vous n'aviez pas été chassé d'un beau château à grands coups de pied dans le derrière... vous ne mangeriez pas ici des cédrats confits et des pistaches.»",
