        "source": "In diesem Zustand leeren und friedlichen Nachdenkens blieb er bis die Turmuhr die dritte Morgenstunde schlug... Dann sank sein Kopf ohne seinen Willen gänzlich nieder, und aus seinen Nüstern strömte sein letzter Atem schwach hervor.",
