          "hollingdale_zarathustra": "'I teach you the Superman. Man is something that should be overcome. What have you done to overcome him?'",
          "parkes_zarathustra": "'I teach you the Overhuman. The human is something that shall be overcome. What have you done to overcome it?'",
          "del_caro_zarathustra": "'I teach you the overman. Human being is something that must be overcome. What have you done to overcome him?'",
          "common_zarathustra": "'I teach you the Superman. Man is something that is to be surpassed. What have ye done to surpass him?'",
          "clancy_zarathustra": "'I teach you the Superman. Man is something that must be overcome. What have you done to overcome him?'",
