    "description": "The crowning masterpiece of modern Russian drama. Chekhov's final play captures the tragicomic decline of the aristocratic landowner Lyubov Ranevskaya, returning to her indebted estate where the magnificent cherry orchard must be sold at auction. The merchant Lopakhin, son of a former serf, buys the orchard and chops it down for summer cottages, symbolizing the vanishing of the old feudal order.",
