        "sectionId": "hugo-silver-candlesticks",
        "source": "L'évêque s'approcha de lui, et lui dit à voix basse: «N'oubliez pas, n'oubliez jamais que vous m'avez promis d'employer cet argent à devenir honnête homme.»",
