        "sectionId": "hugo-silver-candlesticks",
        "source": "L'évêque avait appuyé sur ces paroles avec une sorte de solennité. Il reprit avec gravité: «Jean Valjean, mon frère, vous n'appartenez plus au mal, mais au bien. C'est votre âme que je vous achète; je la retire aux pensées noires et à l'esprit de perdition, et je la donne à Dieu!»",
        "literal": "The bishop had emphasized on these words with a sort of solemnity. He resumed with gravity: 'Jean Valjean, my brother, you not belong more to evil, but to good. It is your soul that I you buy; I it withdraw from thoughts black and from spirit of perdition, and I it give to God!'",
