          "rose_hugo": "The Bishop had emphasized these words with a sort of solemnity. He resumed with gravity: 'Jean Valjean, my brother, you belong no longer to evil, but to good. It is your soul that I am buying from you; I withdraw it from dark thoughts and the spirit of perdition, and I give it to God!'",
