          "fahnestock_macfee_hugo": "He sang: 'I am down on the ground, / 'Tis the fault of Voltaire; / With my nose in the gutter, / 'Tis the fault of...' He did not finish. A second ball... struck him down. That great little soul had just taken flight.",
