        "source": "Und, wie so oft, schickte er sich an, ihm zu folgen... Wenige Minuten vergingen, bis man herbeieilte, um ihn aufzurichten. Man brachte ihn auf sein Zimmer. Und noch desselben Tages empfing eine respektvoll erschütterte Welt die Nachricht von seinem Tode.",
        "literal": "And, as so often, prepared he himself, him to follow... Few minutes passed, until one rushed-there, to him lift-up. One brought him to his room. And still that-same day received a respectfully shaken world the news of his death.",
